import os
import json2

fn main() {
	dir := 'tests/android/results/2026-10-23/maps-canvas-save/'
	observations := {
		'reviewed_by': 'Root agent drove QMP and reviewed live map, place, route-options and failure behavior. transition_review independently inspected origin-query.png and route-selected.png, and checked the manual timeline and fatal serial trace. observer_verify also independently inspected route-selected.png and validated the frozen input receipt.'
		'map': 'Map-before-input.png was captured at 2026-10-23 17:45:16 UTC+3 after the helper detected map-colored pixels; root reviewed the live map.'
		'search': 'Clicked search at 17:45:26 UTC+3 and typed Paris at 17:45:45. Search-paris.png was captured at 17:46:08 before selecting the first suggestion.'
		'place_selection': 'Clicked the first Paris suggestion at 17:46:08 UTC+3. Paris-selected.png at 17:46:29 shows the Paris place panel and photographs according to root visual review. Directions was clicked at 17:46:29.'
		'directions': 'Directions-opened.png was captured at 17:46:52 UTC+3. The standard producer argument was Versailles, France at 17:46:52, but origin-query.png at 17:47:13 visibly reads Versailles, Frace. The first suggestion is Versailles / France and was selected at 17:47:14. Route-selected.png at 17:47:45 visibly shows endpoints Versailles and Paris, Drive 1 hr 9 min (23 km), transit 26 min, walking 4 hr 25, and Preview / Add stops / Share controls over the area map. A distinct route polyline cannot be established from this image. This verifies route-options display, not navigation or the accuracy of the estimates.'
		'preview': 'Clicked Preview at 17:48:04 UTC+3. The application exited on a missing native implementation for android.widget.PopupMenu.native_init()J. Route-preview.png capture at 17:48:36 failed because QMP had exited. Preview and navigation are not verified.'
		'raw_outcome': 'startup_failed; APK-SUITE-EXIT id=google-maps code=1 native_observed=true gtk_x11_absent=true. The raw startup classifier is preserved separately from the observed map/search/place/route-options behavior.'
		'fatal': 'Serial lines 132163–132164: ANDROID-WS-FAIL input or render; UnsatisfiedLinkError: No implementation found for long android.widget.PopupMenu.native_init(), reached through PopupMenu.MenuImpl, PopupMenu constructors, bcfg, bczp.g and the Maps AppBar after Preview. APK exit 1 is recorded at line 132253.'
		'qualification': 'Only framework_canvas_save_flags.v and its framework_startup.v hook differ from Maps241; the Maps/GMS/Store APKs, launcher, native235 and frozen suite239-stream binary are identical. Exact framework111/native83 source archives, seven pre-run identities and seven staged runtime hashes are retained. The prior Canvas.saveLayer overload error does not recur. The new overload delegates to the existing no-flags saveLayer; reaching this UI does not establish complete offscreen-layer rendering semantics. UI processing remains slow, some icons render as squares or black circles, and parts of the bottom panel are clipped. The missing n in the origin query is preserved without assigning a cause. No performance, zoom, location, route-polyline, estimate-accuracy or navigation claim is made.'
	}
	os.write_file(dir + 'observations.json', json2.encode(observations, prettify: true) + '\n')!
	os.write_file(dir + 'README.md', 'Maps242 displays route options from Versailles to Paris: Drive **1 hr 9 min (23 km)**, transit **26 min**, and walking **4 hr 25**, with Preview, Add stops and Share controls. Live map tiles, Paris search, the Paris place panel and photographs also display. Clicking Preview then exits on the missing native implementation for `android.widget.PopupMenu.native_init()`. The preview screenshot failed after exit. A distinct route polyline and navigation are unverified.\n\nThe origin helper sent `Versailles, France`, while the captured query reads `Versailles, Frace`; the first visible suggestion is Versailles / France and was selected. This observation is preserved without attributing its cause. The route screenshot verifies displayed options and estimates, not their accuracy. UI processing remains slow, some icons appear as boxes or black circles, and bottom-panel details are partly clipped.\n\nThis run uses framework242 (111 exact V sources), unchanged native235 (83 sources), and the unchanged frozen suite239-stream binary. Relative to [Maps241](../maps-blur-styles/README.md), only the Canvas saveLayer flags overload generator and its framework hook change. The Maps/GMS/Store APKs, launcher and six staged runtime files other than the framework JAR are identical. Seven pre-run kernel/image/EFI/QEMU/suite hashes and seven staged runtime hashes identify the inputs; exact V archives and selected generated Smali are retained. The added overload delegates to the existing no-flags saveLayer; route-options display does not establish complete offscreen-layer rendering semantics.\n\nThe receipt preserves the raw `startup_failed` classifier, APK exit code 1, complete serial output, screenshots and manual timeline. `observations.json` records screenshot interpretation separately. The independently verified [native235 interpolator precision](../interpolators/README.md) and [streaming staging implementation](../maps-window-insets/README.md) remain unchanged. No performance, zoom, location, estimate-accuracy or navigation claim is made.\n\nFrom the repository root, run `/Users/alex/code/v/v_old -nocache -cc cc run tests/android/results/2026-10-23/maps-canvas-save/validate.v result`. Capture `retain.v inputs` while the completed staged module exists, then `retain.v result` after completion; refresh `retain.v manifest` after recording reviewed observations. The validator checks exact source deltas, unchanged binary inputs, staging provenance and the fatal result separately from screenshot interpretation.\n')!
	mut validator := os.read_file(dir + 'validate.v')!
	old := "\t\tassert log.contains('APK-SUITE-EXIT id=google-maps'), 'Require completed run'"
	assert validator.count(old) == 1
	validator = validator.replace(old, "\t\tassert result['outcome']!.str() == 'startup_failed'\n\t\tassert log.contains('ANDROID-WS-FAIL input or render')\n\t\tassert log.contains('java.lang.UnsatisfiedLinkError: No implementation found for long android.widget.PopupMenu.native_init()')\n\t\tassert log.contains('APK-SUITE-EXIT id=google-maps code=1 native_observed=true gtk_x11_absent=true')\n\t\tassert !log.contains('NoSuchMethodError: No virtual method saveLayer(FFFFLandroid/graphics/Paint;I)I'), 'Prior Canvas overload blocker must be reported if it recurs'")
	old_print := "\t\tprintln('MAPS242-INTEGRITY PASS"
	assert validator.count(old_print) == 1
	validator = validator.replace(old_print, "\t\tassert observations['preview']!.str().len > 0\n\t\tfor name in ['map-before-input.png', 'search-paris.png', 'paris-selected.png',\n\t\t\t'directions-opened.png', 'origin-query.png', 'route-selected.png'] {\n\t\t\tassert os.exists(out + '/run/' + name), name\n\t\t}\n\t\tassert !os.exists(out + '/run/route-preview.png'), 'Preview capture failed after app exit'\n" + old_print)
	os.write_file(dir + 'validate.v', validator)!
	os.cp(@FILE, dir + 'helpers/finalize-maps242.v')!
	for args in [['retain.v', 'manifest'], ['validate.v', 'result']] {
		r := os.exec(['/Users/alex/code/v/v_old', '-nocache', '-cc', 'cc', 'run', dir + args[0], args[1]])
		if args[0] == 'validate.v' {
			os.write_file(dir + 'validation.log', r.output.trim_right('\r\n') + '\n')!
		}
		print(r.output)
		assert r.exit_code == 0, args.str()
	}
}
